#!/usr/bin/env python3
"""Port of the verified kernel-specific printk recovery; never guess its addresses."""
import argparse,os,pathlib,shlex,subprocess
os.umask(0o077)
p=argparse.ArgumentParser();p.add_argument('--host',required=True);p.add_argument('--vmid',type=int,required=True);p.add_argument('--symbol-address',type=lambda x:int(x,0),required=True);p.add_argument('--kaslr-offset',type=lambda x:int(x,0),required=True);p.add_argument('--remote-dir',required=True);p.add_argument('--output',type=pathlib.Path,required=True);a=p.parse_args();assert a.remote_dir.startswith('/')and not a.output.exists()
remote='import socket,json,pathlib,struct,os\nos.umask(0o077)\nroot=pathlib.Path(REMOTE_DIRECTORY);root.mkdir(mode=0o700,exist_ok=False)\ns=socket.socket(socket.AF_UNIX);s.settimeout(10);s.connect(\'/var/run/qemu-server/VM_ID.qmp\');f=s.makefile(\'rwb\',buffering=0);f.readline()\ndef qmp(cmd):\n f.write((json.dumps(cmd)+\'\\\\n\').encode())\n while True:\n  r=json.loads(f.readline())\n  if \'error\' in r:raise RuntimeError(r)\n  if \'return\' in r:return r[\'return\']\nqmp({\'execute\':\'qmp_capabilities\'})\ndef read(addr,size,name):\n p=root/name\n result=qmp({\'execute\':\'human-monitor-command\',\'arguments\':{\'command-line\':f\'memsave {addr:#x} {size} "{p}"\'}})\n if result:raise RuntimeError(result)\n return p.read_bytes()\noffset=OFFSET\nptr=struct.unpack(\'<Q\',read(SYMBOL_ADDRESS+offset,8,\'prb-pointer.bin\'))[0]\nr=read(ptr,88,\'prb-metadata.bin\')\ncount_bits=struct.unpack_from(\'<I\',r,0)[0];size_bits=struct.unpack_from(\'<I\',r,48)[0]\nassert 8<=count_bits<=16 and 16<=size_bits<=26,(count_bits,size_bits)\ndescptr,infoptr=struct.unpack_from(\'<QQ\',r,8);dataptr=struct.unpack_from(\'<Q\',r,56)[0]\ncount=1<<count_bits;size=1<<size_bits\ndesc=read(descptr,count*24,\'prb-descriptors.bin\');infos=read(infoptr,count*88,\'prb-infos.bin\');data=read(dataptr,size,\'prb-text.bin\')\nrecords=[]\nfor i in range(count):\n state,begin,end=struct.unpack_from(\'<QQQ\',desc,i*24)\n if state>>62 not in (1,2):continue\n seq,ts,length=struct.unpack_from(\'<QQH\',infos,i*88)\n if not length or length>size-8:continue\n start=(begin&(size-1))+8\n if start+length>size:continue\n text=data[start:start+length].decode(errors=\'replace\')\n records.append((seq,ts,text))\nrecords.sort()\n(root/\'printk-exact.txt\').write_text(\'\'.join(f\'[{ts/1e9:12.6f}] {text}\\\\n\' for seq,ts,text in records))\nprint(json.dumps({\'records\':len(records),\'kaslr_offset\':hex(offset),\'text_bytes\':size}))\n'
remote=remote.replace('REMOTE_DIRECTORY',repr(a.remote_dir)).replace('VM_ID',str(a.vmid)).replace('SYMBOL_ADDRESS',str(a.symbol_address)).replace('OFFSET',str(a.kaslr_offset))
subprocess.run(['ssh','-o','BatchMode=yes',a.host,'python3','-c',shlex.quote(remote)],check=True)
subprocess.run(['scp','-q',a.host+':'+a.remote_dir+'/printk-exact.txt',str(a.output)],check=True);a.output.chmod(0o600)
